(function(){'use strict';const SchemaHelper={addFAQSchema: function(faqs){if(!faqs||faqs.length===0)return;const faqSchema={"@context": "https://schema.org","@type": "FAQPage","mainEntity": faqs.map(function(faq){return{"@type": "Question","name": faq.question,"acceptedAnswer":{"@type": "Answer","text": faq.answer}};})};this.injectSchema(faqSchema);},addBreadcrumbSchema: function(breadcrumbs){if(!breadcrumbs||breadcrumbs.length===0)return;const breadcrumbSchema={"@context": "https://schema.org","@type": "BreadcrumbList","itemListElement": breadcrumbs.map(function(item,index){return{"@type": "ListItem","position": index+1,"name": item.name,"item": item.url};})};this.injectSchema(breadcrumbSchema);},addHowToSchema: function(howto){if(!howto||!howto.steps)return;const howtoSchema={"@context": "https://schema.org","@type": "HowTo","name": howto.name,"description": howto.description||"","step": howto.steps.map(function(step,index){return{"@type": "HowToStep","name": step.name,"text": step.text,"position": index+1};})};if(howto.totalTime){howtoSchema.totalTime=howto.totalTime;}this.injectSchema(howtoSchema);},addOrganizationSchema: function(org){if(!org)return;const orgSchema={"@context": "https://schema.org","@type": "Organization","name": org.name,"url": org.url,"logo": org.logo,"description": org.description};if(org.sameAs){orgSchema.sameAs=org.sameAs;}if(org.contactPoint){orgSchema.contactPoint={"@type": "ContactPoint","contactType": org.contactPoint.contactType,"email": org.contactPoint.email};}this.injectSchema(orgSchema);},addWebSiteSchema: function(site){if(!site)return;const siteSchema={"@context": "https://schema.org","@type": "WebSite","name": site.name,"url": site.url,"areaServed":{"@type": "Country","name": "India"},"inLanguage": "en-IN"};if(site.searchUrl){siteSchema.potentialAction={"@type": "SearchAction","target":{"@type": "EntryPoint","urlTemplate": site.searchUrl+"?q={search_term_string}"},"query-input": "required name=search_term_string"};}this.injectSchema(siteSchema);},injectSchema: function(schemaObject){const script=document.createElement('script');script.type='application/ld+json';script.text=JSON.stringify(schemaObject);document.head.appendChild(script);},autoGenerateBreadcrumbs: function(){const path=window.location.pathname;const parts=path.split('/').filter(Boolean);const baseUrl=window.location.origin;const breadcrumbs=[{name: "Home",url: baseUrl+"/"}];let currentPath='';parts.forEach(function(part,index){currentPath+='/'+part;let name=part.replace('.html','').replace(/-/g,' ');name=name.charAt(0).toUpperCase()+name.slice(1);breadcrumbs.push({name: name,url: baseUrl+currentPath});});return breadcrumbs;}};window.SchemaHelper=SchemaHelper;if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){const breadcrumbs=SchemaHelper.autoGenerateBreadcrumbs();if(breadcrumbs.length>1){SchemaHelper.addBreadcrumbSchema(breadcrumbs);}});}else{const breadcrumbs=SchemaHelper.autoGenerateBreadcrumbs();if(breadcrumbs.length>1){SchemaHelper.addBreadcrumbSchema(breadcrumbs);}}})();